'use strict';
/* Geografia Irada — kit de ilustração (frente de Ilustração e identidade; guia de arte §4).

   OBJETOS DE PEÇAS (renderizados em 3D, fundo transparente, contorno de adesivo índigo; WebP 512 px embutido):
     arte(nome, { classe, alt, px }) → '<img class="arte arte-<nome> …">' pronto para innerHTML (alt vazio = decorativo).
     urlArte(nome) → data URI (para <img>, canvas ou textura do Three.js). ARTE = { nome: descrição } lista os 63 objetos.
     Tamanhos de uso: 48 (chip), 96 (botão, selo), 160–220 (cabeçalho, conselheiro), 360 (destaque). Nunca acima de 512.
     Classes prontas em css/arte.css: .arte.chip · .arte.botao · .arte.cabecalho · .arte.destaque.
     Bandeiras também por potência: arte('bandeira-brasil') = arte('bandeira-circulo'). Mascote: 'globo-irado-<reação>'.
     Gerados por ferramentas/renderizar-arte.mjs (modelos em ferramentas/vitrine-arte.html?render=<nome>); arquivos em img/arte/.

   ORNAMENTOS (HTML/SVG pronto; aparência em css/arte.css; usam FORMAS/CORES_GUIA/nomeCurto de ui.js na hora da chamada):
     cabecalhoJornal({ ano, mandato, total, extra, compacto, preco }) · seloExtra(texto)
     tarjaPlantao({ manchete, texto, lugar, ano }) · vinhetaPlantao({ crise, sub }) + animarVinheta(el) → timeline GSAP (1,6 s)
     fita(texto, { cor, classe: 'marca' | 'clara' }) · conquista(emoji | número, { cor, fita, rotulo, classe: 'grande' | 'pequena', alt })
     tiquete(html, { cor, icone, direita }) · ponteiroVez(texto)
   GRÁFICOS (SVG; cor = id de equipe/categoria do guia, 'ouro', 'amarelo'… ou hex):
     graficoTijolos([{ pid, valor, rotulo? }], { max, tijolos, unidade, casas, tema })   barras = pilhas de tijolos
     graficoLinhas([{ pid, pontos }], { anos, min, max, destaque, casas, unidade })     linhas com pinos
     cascata([{ texto, valor }])  ·  tijolosCO2([{ pid, valor }])  ·  matrizEnergia(limpas, total)
   MEDIDORES (SVG): termometroTijolos(temp) · relogioJuizo(segundos, { grande }) · ponteiroEnergia(0–100)
     · anelProgresso(n, total) · encaixes([pid | cor…], total)
   Peças para quem desenha os próprios SVGs: Arte.tijoloFrente(x, y, w, h, face, lado, { pinos, rotulo }), Arte.formaSVG(pid, cx, cy, lado),
     Arte.corPeca(cor) → [face, lado].
   Padrões de fundo (só CSS): .fundo-pinos, .fundo-planta, .fundo-ondas, .fundo-raios, .fundo-zebra. */

// Nomes definitivos do kit (guia §4.4) com o que cada um mostra
const ARTE = {
  'jornal': 'Jornal Mundial: folhas empilhadas com a manchete e o selo EXTRA!',
  'camera-tv': 'Câmera de estúdio do Plantão Global, com a luz de gravando acesa',
  'microfone': 'Microfone de repórter com a canopla do Plantão Global',
  'urna': 'Urna de votação translúcida com uma cédula entrando',
  'martelo': 'Martelo da assembleia, prestes a bater',
  'carimbo': 'Carimbo de borracha com a marca de tinta no chão',
  'trofeu': 'Troféu de peças com a placa 2050',
  'medalha-ouro': 'Medalha de ouro (1º lugar) com fita',
  'medalha-prata': 'Medalha de prata (2º lugar) com fita',
  'medalha-bronze': 'Medalha de bronze (3º lugar) com fita',
  'globo': 'Globo de mesa de peças, inclinado como o eixo da Terra',
  'planeta': 'Planeta de peças solto, sem base (vinheta do Plantão, selos, "o mundo")',
  'termometro': 'Termômetro de peças com a coluna subindo e uma gota de suor',
  'relogio-juizo': 'Relógio do Juízo Final com sininhos, a três minutos da meia-noite',
  'navio': 'Navio cargueiro com contêineres coloridos e esteira',
  'aviao': 'Avião em curva com rastro de nuvenzinhas',
  'pomba': 'Pomba da paz com ramo de oliveira sobre uma nuvem',
  'aperto-maos': 'Aperto de mãos: acordo fechado',
  'moedas': 'Pilha de moedas com uma em pé',
  'caixa-alimentos': 'Caixote de alimentos: espigas e folhas transbordando',
  'caixa-energia': 'Caixote de energia: baterias com raio',
  'caixa-minerais': 'Caixote de minerais: cristais lilás e turquesa',
  'caixa-tecnologia': 'Caixote de tecnologia: chips com pinos dourados',
  'pinos-cp': 'Capital Político: peça redonda amarela com pino grande',
  'megafone': 'Megafone com arcos de som',
  'prancheta': 'Prancheta com folha de objetivos marcados',
  'mapa-enrolado': 'Mapa meio enrolado com fita vermelha',
  'manual': 'Livro "Manual do Diplomata" entreaberto, com marcador',
  'engrenagem': 'Engrenagem de ajustes com pino amarelo',
  'cadeado': 'Cadeado fechado',
  'cadeado-aberto': 'Cadeado aberto',
  'envelope-secreto': 'Envelope secreto com lacre e carimbo CONFIDENCIAL',
  'lupa': 'Lupa aumentando uma peça',
  'maleta': 'Maleta diplomática com adesivos de viagem',
  'pulpito': 'Púlpito da assembleia com microfone e o globo de peças',
  'binoculo': 'Binóculo de peças',
  'ampulheta': 'Ampulheta com a areia caindo',
  'dossie': 'Dossiê confidencial com retrato clipado',
  'tablet-voto': 'Tablet de votação com os botões sim, não e abstenção',
  'escudo': 'Escudo de tijolos com uma pomba impressa',
  'lampada': 'Lâmpada acesa: ideia e ciência',
  'pilha-tijolos': 'Pilha de tijolos nas cores das equipes, com um caindo',
  'bandeira-circulo': 'Bandeira da Equipe Verde (Brasil), com o círculo',
  'bandeira-quadrado': 'Bandeira da Equipe Azul (Estados Unidos), com o quadrado',
  'bandeira-triangulo': 'Bandeira da Equipe Vermelha (China), com o triângulo',
  'bandeira-estrela': 'Bandeira da Equipe Roxa (União Europeia), com a estrela',
  'bandeira-losango': 'Bandeira da Equipe Laranja (Índia), com o losango',
  'bandeira-hexagono': 'Bandeira da Equipe Rosa (Rússia), com o hexágono',
  'bandeira-cruz': 'Bandeira da Equipe Turquesa (Reino Unido), com a cruz',
  'bandeira-anel': 'Bandeira da Equipe Grafite (Japão), com o anel',
  'bandeira-gota': 'Bandeira da Equipe Lima (Austrália), com a gota',
  'bandeira-pentagono': 'Bandeira da Equipe Bordô (Nova Zelândia), com o pentágono',
  'bandeira-octogono': 'Bandeira da Equipe Marrom (África do Sul), com o octógono',
  'bandeira-escudo': 'Bandeira da Equipe Coral (Nigéria), com o escudo',
  'bandeira-trapezio': 'Bandeira da Equipe Celeste (Egito), com o trapézio',
  'caixa-ajuda': 'Caixas de ajuda humanitária com coração',
  'tenda': 'Tenda de acolhimento com coração e lampião aceso',
  'satelite': 'Satélite em órbita sobre placa de peças',
  'foguete': 'Foguete na plataforma de lançamento',
  'turbina': 'Turbina eólica girando',
  'painel-solar': 'Painel solar brilhando',
  'fabrica': 'Fábrica com chaminé',
  'escola': 'Escola',
  'hospital': 'Hospital com o "H" azul',
  'selo-missao-2050': 'Selo "MISSÃO 2050"',
  'globo-irado-feliz': 'Globo Irado, o mascote, sorrindo de lado',
  'globo-irado-pensando': 'Globo Irado pensando, com a luva no queixo',
  'globo-irado-susto': 'Globo Irado assustado, com os óculos escorregando',
  'globo-irado-triste': 'Globo Irado triste',
  'globo-irado-comemorar': 'Globo Irado comemorando de braços para cima',
};
// Enquanto um objeto não tem render, mostra o ícone Fluent mais próximo (some quando o render existir)
const ARTE_PROVISORIA = {
  'jornal': '📰', 'camera-tv': '🎬', 'microfone': '🎤', 'urna': '🗳', 'martelo': '⚖', 'carimbo': '✅', 'trofeu': '🏆',
  'medalha-ouro': '🥇', 'medalha-prata': '🥈', 'medalha-bronze': '🥉', 'globo': '🌍', 'termometro': '🌡', 'relogio-juizo': '⏰',
  'planeta': '🌍', 'navio': '🚢', 'aviao': '🌐', 'pomba': '🕊', 'aperto-maos': '🤝', 'moedas': '💰', 'caixa-alimentos': '🌾', 'caixa-energia': '🔋',
  'caixa-minerais': '💎', 'caixa-tecnologia': '💻', 'pinos-cp': '🧱', 'megafone': '📣', 'prancheta': '📋', 'mapa-enrolado': '🗺',
  'manual': '📚', 'engrenagem': '⚙', 'cadeado': '🔒', 'cadeado-aberto': '🔓', 'envelope-secreto': '📜', 'lupa': '🔍',
  'maleta': '🧳', 'pulpito': '🎙', 'binoculo': '🔎', 'ampulheta': '⏳', 'dossie': '🗂', 'tablet-voto': '📱', 'escudo': '🛡',
  'lampada': '💡', 'pilha-tijolos': '🧱', 'caixa-ajuda': '📦', 'tenda': '🏠', 'satelite': '🛰', 'foguete': '🚀', 'turbina': '⚡',
  'painel-solar': '☀', 'fabrica': '🏭', 'escola': '🎓', 'hospital': '💉', 'selo-missao-2050': '🎯',
};
const nomeArte = nome => {
  const n = String(nome ?? '');
  const p = n.match(/^bandeira-(\w+)$/);
  const forma = p && typeof CORES_GUIA !== 'undefined' ? CORES_GUIA[p[1]]?.forma : null;   // a forma da potência vem de js/ui.js (fonte única)
  return forma ? 'bandeira-' + forma : n;
};
function urlArte(nome) {
  const n = nomeArte(nome);
  if (ARTE_IMG[n]) return ARTE_IMG[n];
  if (n.startsWith('bandeira-')) return typeof urlIcone === 'function' ? urlIcone('🪧') : '';
  if (n.startsWith('globo-irado')) return typeof urlIcone === 'function' ? urlIcone('🌍') : '';
  return ARTE_PROVISORIA[n] && typeof urlIcone === 'function' ? urlIcone(ARTE_PROVISORIA[n]) : '';
}
function arte(nome, { classe = '', alt = '', px = 0 } = {}) {
  const n = nomeArte(nome), u = urlArte(n);
  if (!u) return '';
  const tam = px ? ` width="${px}" height="${px}"` : ' width="512" height="512"';
  const prov = ARTE_IMG[n] ? '' : ' arte-provisoria';
  return `<img class="arte arte-${n}${prov}${classe ? ' ' + classe : ''}" src="${u}"${tam} alt="${String(alt).replace(/"/g, '&quot;')}" draggable="false">`;
}

// =====================================================================================================
// ORNAMENTOS (guia §4.5–4.8): HTML/SVG pronto; a aparência mora em css/arte.css
// =====================================================================================================
const Arte = (() => {
  const TINTA_A = '#1A1433';
  const escA = t => String(t ?? '').replace(/[&<>"']/g, c => `&#${c.charCodeAt(0)};`);
  const n1A = v => Math.round(v * 10) / 10;
  const CORES_PECA = { ouro: ['#FFC93C', '#C98A00'], prata: ['#D5DEEA', '#8E9BB0'], bronze: ['#E79A5C', '#A55A2A'], amarelo: ['#FFD21F', '#B98A00'],
    verde: ['#3CD46A', '#1F9A47'], vermelho: ['#F0303A', '#A3141F'], ladrilho: ['#FFF9EC', '#B3AA98'], anil: ['#3550C8', '#141F66'], tinta: ['#2E2752', '#17122E'] };
  // [face, lado] de uma cor do guia: id de equipe, categoria, ouro/prata/bronze, amarelo… ou um hex
  function corPeca(cor) {
    if (Array.isArray(cor)) return cor;
    if (CORES_PECA[cor]) return CORES_PECA[cor];
    const g = typeof CORES_GUIA !== 'undefined' ? CORES_GUIA[cor] : null;
    if (g?.cor) return [g.cor, g.lado || mistA(g.cor, TINTA_A, .36)];
    return [cor || '#FFD21F', mistA(cor || '#FFD21F', TINTA_A, .36)];
  }
  function mistA(a, b, t) {
    const p = h => [1, 3, 5].map(i => parseInt(h.substr(i, 2), 16));
    const [x, y] = [p(a), p(b)];
    return '#' + x.map((v, i) => Math.round(v * (1 - t) + y[i] * t).toString(16).padStart(2, '0')).join('');
  }
  const icoA = (e, px) => (typeof imgIcone === 'function' ? imgIcone(e, px) : '');
  const formaA = pid => (typeof CORES_GUIA !== 'undefined' && CORES_GUIA[pid]?.forma && window.FORMAS ? window.FORMAS[CORES_GUIA[pid].forma] : null);
  const ehEmoji = t => /^\p{Extended_Pictographic}/u.test(String(t ?? ''));
  // forma da equipe dentro de um SVG: centro (cx, cy), lado t
  const formaSVG = (pid, cx, cy, t, { branca = false, traco = 9 } = {}) => {
    const d = formaA(pid);
    if (!d) return '';
    const s = t / 100;
    return `<path d="${d}" transform="translate(${n1A(cx - t / 2)} ${n1A(cy - t / 2)}) scale(${s.toFixed(4)})" fill="${branca ? '#FFFFFF' : corPeca(pid)[0]}" stroke="${TINTA_A}" stroke-width="${traco}" stroke-linejoin="round" paint-order="stroke"/>`;
  };

  // ---------- Jornal Mundial ----------
  function cabecalhoJornal({ ano = 2026, mandato = 1, total = 6, extra = false, compacto = false, preco = '1 pino' } = {}) {
    const globo = icoA('🌍', 48);
    if (compacto) return `<div class="jornal-faixa compacta peca vermelha">${globo}<span class="jornal-nome">Jornal Mundial</span></div>`;
    return `<header class="jornal-cab"><div class="jornal-faixa peca pinos vermelha">${globo}<span class="jornal-nome">Jornal Mundial</span>${globo}</div>` +
      `<div class="jornal-edicao">Edição ${escA(ano)}<span class="sep" aria-hidden="true"></span>Mandato ${escA(mandato)} de ${escA(total)}<span class="sep" aria-hidden="true"></span>Preço: ${escA(preco)}</div>` +
      (extra ? seloExtra(typeof extra === 'string' ? extra : 'EXTRA!') : '') + '</header>';
  }
  // Estrela amarela de 12 pontas com lateral, contorno e brilho
  function seloExtra(texto = 'EXTRA!') {
    const pts = r => Array.from({ length: 24 }, (_, i) => { const a = (i / 24) * Math.PI * 2 - Math.PI / 2, rr = i % 2 ? r * .8 : r; return `${n1A(60 + Math.cos(a) * rr)},${n1A(60 + Math.sin(a) * rr)}`; }).join(' ');
    return `<svg class="selo-extra" viewBox="0 0 120 128" aria-hidden="true"><g stroke="${TINTA_A}" stroke-width="7" stroke-linejoin="round">` +
      `<polygon points="${pts(54)}" transform="translate(0 6)" fill="#B98A00"/><polygon points="${pts(54)}" fill="#FFD21F"/></g>` +
      `<polygon points="${pts(54)}" fill="none" stroke="#fff" stroke-opacity=".55" stroke-width="3" transform="translate(60 60) scale(.86) translate(-60 -60)" stroke-dasharray="40 300"/>` +
      `<text x="60" y="67" text-anchor="middle" font-size="${n1A(Math.min(24, 108 / Math.max(4, texto.length)))}" fill="${TINTA_A}" style="font-family:'Titan One',sans-serif">${escA(texto)}</text></svg>`;
  }

  // ---------- Plantão Global ----------
  function tarjaPlantao({ manchete = '', texto = '', lugar = '', ano = '' } = {}) {
    return `<div class="tarja-plantao"><div class="tarja-topo"><span class="tarja-marca peca pinos vermelha">Plantão</span>` +
      `<span class="tarja-vivo ao-vivo">Ao vivo</span>` + (lugar ? `<span class="tarja-lugar">${icoA('📍', 40)}${escA(lugar)}</span>` : '') +
      (ano ? `<span class="tarja-ano">${escA(ano)}</span>` : '') + '</div>' +
      `<div class="tarja-corpo peca"><h2 class="tarja-manchete">${escA(manchete)}</h2>${texto ? `<p class="tarja-texto">${escA(texto)}</p>` : ''}</div></div>`;
  }
  // Anel de órbita de peças redondas amarelas: o anel fica parado e as peças correm por ele (animarVinheta);
  // as que passam por trás do globo somem atrás dele
  const ORBITAS = [{ inclina: -14, n: 14, rx: 47, ry: 13 }, { inclina: 20, n: 12, rx: 43, ry: 11 }];
  function posicionarOrbitas(el, fase = 0) {
    el.querySelectorAll('.vp-orbita').forEach((svg, k) => {
      const o = ORBITAS[k], a0 = o.inclina * Math.PI / 180;
      svg.querySelectorAll('.vp-peca').forEach((p, i) => {
        const a = (i / o.n + fase * (k ? -.7 : 1)) * Math.PI * 2, x = Math.cos(a) * o.rx, y = Math.sin(a) * o.ry;
        const X = 50 + x * Math.cos(a0) - y * Math.sin(a0), Y = 50 + x * Math.sin(a0) + y * Math.cos(a0), tras = Math.sin(a) < 0;
        const atras = tras && Math.hypot(X - 50, Y - 50) < 30, esc = tras ? .78 : 1.05;
        p.setAttribute('transform', `translate(${n1A(X)} ${n1A(Y)}) scale(${esc})`); p.style.opacity = atras ? 0 : tras ? .8 : 1;
      });
    });
  }
  function orbitaPlantao({ inclina, n, rx, ry }) {
    const peca = '<g class="vp-peca"><ellipse cy="1.3" rx="3.3" ry="2.6" fill="#B98A00" stroke="#1A1433" stroke-width="1.2"/><ellipse rx="3.3" ry="2.6" fill="#FFD21F" stroke="#1A1433" stroke-width="1.2"/><ellipse cx="-1" cy="-.8" rx="1.1" ry=".6" fill="#fff" fill-opacity=".85"/></g>';
    return `<svg class="vp-orbita" viewBox="0 0 100 100" aria-hidden="true"><ellipse cx="50" cy="50" rx="${rx}" ry="${ry}" transform="rotate(${inclina} 50 50)" fill="none" stroke="#FFD21F" stroke-opacity=".45" stroke-width="1.1" stroke-dasharray="2 2.4"/>${peca.repeat(n)}</svg>`;
  }
  function vinhetaPlantao({ crise = false, sub = '' } = {}) {
    const t = document.createElement('template');
    t.innerHTML = `<div class="vinheta-plantao${crise ? ' crise' : ''}" role="img" aria-label="Plantão Global"><div class="vp-listras"></div>` +
      `<div class="vp-palco"><div class="vp-globo">${typeof arte === 'function' ? arte('planeta') : ''}${ORBITAS.map(orbitaPlantao).join('')}</div>` +
      `<div class="vp-letreiro"><span class="vp-plantao peca pinos">Plantão</span><span class="vp-global peca">Global</span></div>` +
      `<p class="vp-sub">${escA(sub)}</p></div></div>`;
    posicionarOrbitas(t.content);
    return t.innerHTML;
  }
  // Entrada da vinheta (1,6 s; pulável com tl.progress(1)): listras varrem, globo entra, peças correm na órbita, letreiro bate
  function animarVinheta(el) {
    if (!el || typeof gsap === 'undefined') return null;
    const reduzido = matchMedia('(prefers-reduced-motion: reduce)').matches || document.documentElement.classList.contains('rm');
    const tl = gsap.timeline();
    if (reduzido) return tl.fromTo(el, { opacity: 0 }, { opacity: 1, duration: .2 });
    const giro = { fase: 0 };
    tl.fromTo(el.querySelector('.vp-listras'), { xPercent: -110 }, { xPercent: 0, duration: .35, ease: 'power3.out' })
      .fromTo(el.querySelector('.vp-globo'), { scale: 0, rotation: -40 }, { scale: 1, rotation: 0, duration: .55, ease: 'back.out(1.6)' }, .2)
      .to(giro, { fase: .35, duration: 1.6, ease: 'power1.out', onUpdate: () => posicionarOrbitas(el, giro.fase) }, .2)
      .fromTo(el.querySelector('.vp-plantao'), { scale: 2.4, rotation: -25, opacity: 0 }, { scale: 1, rotation: -4, opacity: 1, duration: .28, ease: 'back.out(2.2)' }, .62)
      .fromTo(el.querySelector('.vp-global'), { y: 40, opacity: 0 }, { y: 0, opacity: 1, duration: .25, ease: 'back.out(2)' }, .8)
      .fromTo(el.querySelector('.vp-sub'), { y: 20, opacity: 0 }, { y: 0, opacity: 1, duration: .25, ease: 'power2.out' }, .95);
    return tl;
  }

  // ---------- Fita com pontas em cauda de andorinha ----------
  function fita(texto, { cor = 'amarelo', classe = '' } = {}) {
    const [f, l] = corPeca(cor);
    const cauda = l2 => `<svg class="fita-cauda ${l2}" viewBox="0 0 66 88" aria-hidden="true"><path class="c-face" d="M66 18H4l13 35L4 88h62Z" stroke="${TINTA_A}" stroke-width="4.5" stroke-linejoin="round"/>` +
      `<path d="M10 25h50" stroke="#fff" stroke-opacity=".35" stroke-width="3" stroke-linecap="round"/><path class="c-dobra" d="M46 70h20v18Z" stroke="${TINTA_A}" stroke-width="4.5" stroke-linejoin="round"/></svg>`;
    return `<span class="fita${classe ? ' ' + classe : ''}" style="--cor:${f};--cor-lado:${l}">${cauda('e')}<span class="fita-meio">${escA(texto)}</span>${cauda('d')}</span>`;
  }

  // ---------- Selo de conquista (peça redonda com anel de 10 pinos) ----------
  function conquista(conteudo, { cor = 'ouro', fita: comFita = false, rotulo = '', classe = '', alt = '' } = {}) {
    const [f, l] = corPeca(cor), topo = mistA(f, '#FFFFFF', .22), miolo = mistA(f, l, .18);
    let s = `<svg viewBox="0 0 100 ${comFita ? 138 : 106}" aria-hidden="true">`;
    if (comFita) s += `<g stroke="${TINTA_A}" stroke-width="4" stroke-linejoin="round"><path d="M30 66 16 128l14-8 9 13 13-61Z" fill="#3550C8"/><path d="M70 66l14 62-14-8-9 13-13-61Z" fill="#3550C8"/></g>` +
      `<path d="M27 80 21 110M73 80l6 30" stroke="#FFD21F" stroke-width="5"/>`;
    s += `<g stroke="${TINTA_A}" stroke-width="5"><circle cx="50" cy="55" r="45" fill="${l}"/><circle cx="50" cy="50" r="45" fill="${f}"/></g>`;
    s += `<path d="M13 42a38 38 0 0 1 74 0" fill="none" stroke="#fff" stroke-opacity=".45" stroke-width="4.5" stroke-linecap="round"/>`;
    for (let i = 0; i < 10; i++) {   // pinos em relevo, da mesma cor da peça
      const a = i / 10 * Math.PI * 2 - Math.PI / 2, x = n1A(50 + Math.cos(a) * 36.5), y = n1A(50 + Math.sin(a) * 36.5);
      s += `<g transform="translate(${x} ${y})"><circle cy="1.8" r="5.4" fill="${l}" stroke="${TINTA_A}" stroke-width="1.8"/><circle r="5.4" fill="${topo}" stroke="${TINTA_A}" stroke-width="1.8"/><ellipse cx="-1.7" cy="-1.9" rx="2.3" ry="1.4" fill="#fff" fill-opacity=".9"/></g>`;
    }
    s += `<circle cx="50" cy="50" r="27" fill="${l}" stroke="${TINTA_A}" stroke-width="3.6"/><circle cx="50" cy="51.5" r="25" fill="${miolo}"/><path d="M28 48a22 22 0 0 1 44 0" fill="none" stroke="${TINTA_A}" stroke-opacity=".12" stroke-width="4"/>`;
    if (ehEmoji(conteudo)) { const u = typeof urlIcone === 'function' ? urlIcone(conteudo) : ''; if (u) s += `<image href="${u}" x="26" y="27" width="48" height="48"/>`; }
    else if (conteudo !== undefined && conteudo !== '') { const t = String(conteudo); s += `<text x="50" y="${t.length > 2 ? 58 : 63}" text-anchor="middle" font-size="${t.length > 2 ? 20 : t.length > 1 ? 28 : 34}" fill="${TINTA_A}">${escA(t)}</text>`; }
    s += '</svg>';
    const r = rotulo ? `<span class="conquista-rotulo">${escA(rotulo)}</span>` : '';
    return `<span class="conquista${classe ? ' ' + classe : ''}"${alt ? ` role="img" aria-label="${escA(alt)}"` : ''}>${s}${r}</span>`;
  }

  // ---------- Tíquete ----------
  function tiquete(html, { cor = 'amarelo', icone = '', direita = false, classe = '' } = {}) {
    const [f, l] = corPeca(cor);
    const ic = ehEmoji(icone) ? icoA(icone, 64) : icone;
    return `<div class="tiquete${direita ? ' direita' : ''}${classe ? ' ' + classe : ''}" style="--cor:${f};--cor-lado:${l}"><div class="tiquete-forma">` +
      `<div class="tiquete-canhoto">${ic}</div><div class="tiquete-corpo">${html}</div></div></div>`;
  }
  const ponteiroVez = (texto = 'VEZ') => `<span class="ponteiro-vez" aria-hidden="true">${escA(texto)}</span>`;

  // ---------- Gráficos ----------
  // Tijolo 2×2 visto de frente (face + lateral + brilho + contorno); x, y = canto de cima; topo = pinos
  function tijoloFrente(x, y, w, h, face, lado, { pinos = 0, rotulo = '' } = {}) {
    const L = h * .24;   // lateral
    let s = `<g transform="translate(${n1A(x)} ${n1A(y)})">`;
    for (let i = 0; i < pinos; i++) {
      const px = w * (i + .5) / pinos, pw = w * .26;
      s += `<path d="M${n1A(px - pw)} ${n1A(-h * .2)}v${n1A(h * .26)}h${n1A(pw * 2)}v${n1A(-h * .26)}Z" fill="${lado}" stroke="${TINTA_A}" stroke-width="2.6" stroke-linejoin="round"/>` +
        `<ellipse cx="${n1A(px)}" cy="${n1A(-h * .2)}" rx="${n1A(pw)}" ry="${n1A(h * .1)}" fill="${mistA(face, '#FFFFFF', .3)}" stroke="${TINTA_A}" stroke-width="2.6"/>`;
    }
    s += `<rect width="${w}" height="${h}" rx="${n1A(h * .16)}" fill="${lado}" stroke="${TINTA_A}" stroke-width="3"/>` +
      `<rect x="1.5" y="1.5" width="${n1A(w - 3)}" height="${n1A(h - L - 1.5)}" rx="${n1A(h * .12)}" fill="${face}"/>` +
      `<rect x="${n1A(w * .1)}" y="${n1A(h * .12)}" width="${n1A(w * .8)}" height="${n1A(h * .1)}" rx="${n1A(h * .05)}" fill="#fff" fill-opacity=".5"/>`;
    if (rotulo) s += `<text x="${n1A(w / 2)}" y="${n1A((h - L) * .74)}" text-anchor="middle" font-size="${n1A(h * .42)}" fill="#fff">${rotulo}</text>`;   // rótulo pode ter <tspan>
    return s + '</g>';
  }
  // Barras = pilhas de tijolos. colunas: [{ pid, valor, rotulo?, cor? }]; opcoes: { max, tijolos: 10, unidade, tema: 'claro'|'escuro', casas }
  function graficoTijolos(colunas, { max, tijolos = 10, unidade = '', tema = 'claro', casas = 0, titulo = '' } = {}) {
    const topo = max ?? Math.max(1, ...colunas.map(c => c.valor)), n = colunas.length, muitas = n > 8, W = 58, H = 22, GAP = muitas ? 16 : 34;   // 13 potências: colunas coladas e sem o nome (a forma identifica; a legenda vem em HTML)
    const larg = n * W + (n - 1) * GAP + 40, alt = tijolos * H + 112, base = alt - 64, txt = tema === 'escuro' ? '#fff' : TINTA_A;
    let s = `<svg class="grafico tijolos" viewBox="0 0 ${larg} ${alt}" role="img" aria-label="${escA(titulo || colunas.map(c => `${c.rotulo ?? nomeA(c.pid)}: ${fmtA(c.valor, casas)}${unidade}`).join('; '))}">`;
    s += `<rect x="4" y="${base}" width="${larg - 8}" height="20" rx="6" fill="#98A6C2" stroke="${TINTA_A}" stroke-width="3"/><rect x="6" y="${base + 1.5}" width="${larg - 12}" height="12" rx="5" fill="#E3E9F4"/>`;
    colunas.forEach((c, i) => {
      const [f, l] = corPeca(c.cor ?? c.pid), qt = Math.max(c.valor > 0 ? 1 : 0, Math.round(Math.min(c.valor, topo) / topo * tijolos)), x = 20 + i * (W + GAP);
      s += `<g class="serie" data-id="${escA(c.pid ?? i)}">`;
      for (let k = 0; k < qt; k++) s += tijoloFrente(x, base - (k + 1) * H + 1, W, H, f, l, { pinos: k === qt - 1 ? 2 : 0 });
      const yv = base - qt * H - (qt ? 16 : 6);
      s += `<text class="valor" x="${x + W / 2}" y="${yv}" text-anchor="middle" font-size="28" fill="${txt}"${tema === 'escuro' ? ` stroke="${TINTA_A}" stroke-width="6"` : ''}>${escA(fmtA(c.valor, casas))}${escA(unidade)}</text>`;
      s += formaSVG(c.pid, x + W / 2, base + 10, muitas ? 34 : 24) + (muitas ? '' : `<text class="rot" x="${x + W / 2}" y="${base + 50}" text-anchor="middle" font-size="23" fill="${txt}">${escA(c.rotulo ?? nomeA(c.pid))}</text>`) + '</g>';
    });
    return s + '</svg>';
  }
  const fmtA = (v, casas = 0) => Number(v).toLocaleString('pt-BR', { minimumFractionDigits: casas, maximumFractionDigits: casas });
  const nomeA = pid => (typeof nomeCurto === 'function' ? nomeCurto(pid) : pid ?? '');
  // Linhas com pinos. series: [{ pid, pontos: [n…], cor? }]; opcoes: { anos, min, max, destaque, largura, altura, casas, unidade }
  function graficoLinhas(series, { anos = [], min, max, destaque = null, largura = 720, altura = 340, casas = 0, unidade = '', tema = 'claro', titulo = '' } = {}) {
    const todos = series.flatMap(s => s.pontos), lo = min ?? Math.min(...todos), hi = max ?? Math.max(...todos), n = Math.max(...series.map(s => s.pontos.length));
    const E = 70, D = 40, C = 24, B = 46, w = largura - E - D, h = altura - C - B, txt = tema === 'escuro' ? '#fff' : TINTA_A;
    const X = i => E + (n < 2 ? w / 2 : i / (n - 1) * w), Y = v => C + h - (v - lo) / ((hi - lo) || 1) * h;
    let s = `<svg class="grafico linhas" viewBox="0 0 ${largura} ${altura}" role="img" aria-label="${escA(titulo || 'Gráfico de linhas')}">`;
    for (let k = 0; k <= 4; k++) { const v = lo + (hi - lo) * k / 4, y = Y(v); s += `<path d="M${E} ${n1A(y)}H${E + w}" stroke="${txt}" stroke-opacity=".14" stroke-width="2" stroke-dasharray="7 7"/><text x="${E - 12}" y="${n1A(y + 8)}" text-anchor="end" font-size="22" fill="${txt}" fill-opacity=".8">${escA(fmtA(v, casas))}${escA(unidade)}</text>`; }
    anos.forEach((a, i) => { if (i < n) s += `<text x="${n1A(X(i))}" y="${altura - 12}" text-anchor="middle" font-size="22" fill="${txt}" fill-opacity=".8">${escA(a)}</text>`; });
    const ordem = [...series].sort((a, b) => (a.pid === destaque) - (b.pid === destaque));
    for (const sr of ordem) {
      const apagada = destaque && sr.pid !== destaque, [f] = apagada ? ['#C9CED6'] : corPeca(sr.cor ?? sr.pid), pts = sr.pontos.map((v, i) => `${n1A(X(i))},${n1A(Y(v))}`).join(' ');
      s += `<g class="serie${apagada ? ' apagada' : ''}" data-id="${escA(sr.pid)}">`;
      s += apagada ? `<polyline points="${pts}" fill="none" stroke="${f}" stroke-width="5" stroke-linejoin="round" stroke-linecap="round"/>`
        : `<polyline points="${pts}" fill="none" stroke="${TINTA_A}" stroke-width="11" stroke-linejoin="round" stroke-linecap="round"/><polyline points="${pts}" fill="none" stroke="${f}" stroke-width="6" stroke-linejoin="round" stroke-linecap="round"/>`;
      if (!apagada) sr.pontos.forEach((v, i) => { if (i < sr.pontos.length - 1) s += `<circle cx="${n1A(X(i))}" cy="${n1A(Y(v))}" r="6.5" fill="${f}" stroke="${TINTA_A}" stroke-width="2.6"/><circle cx="${n1A(X(i) - 2)}" cy="${n1A(Y(v) - 2.2)}" r="2" fill="#fff" fill-opacity=".9"/>`; });
      const u = sr.pontos.length - 1;
      if (u >= 0) s += apagada ? `<circle cx="${n1A(X(u))}" cy="${n1A(Y(sr.pontos[u]))}" r="5" fill="${f}"/>` : formaSVG(sr.pid, X(u), Y(sr.pontos[u]), 24);
      s += '</g>';
    }
    return s + '</svg>';
  }
  // Cascata de causas do balanço: [{ texto, valor }] → barras de tijolinhos a partir do eixo central (+ direita, − esquerda)
  function cascata(causas, { tema = 'claro', titulo = 'Por que mudou' } = {}) {
    const lista = causas.slice(0, 4), maior = Math.max(1, ...lista.map(c => Math.abs(c.valor))), por = Math.max(1, Math.ceil(maior / 8));
    const R = 360, EIXO = 640, TW = 30, TH = 34, LH = 54, alt = lista.length * LH + 16, txt = tema === 'escuro' ? '#fff' : TINTA_A;
    let s = `<svg class="grafico cascata" viewBox="0 0 1000 ${alt}" role="img" aria-label="${escA(titulo + ': ' + lista.map(c => `${c.texto} ${c.valor > 0 ? '+' : '−'}${Math.abs(c.valor)}`).join('; '))}">`;
    s += `<path d="M${EIXO} 4V${alt - 4}" stroke="${txt}" stroke-width="3" stroke-linecap="round" stroke-opacity=".5"/>`;
    lista.forEach((c, i) => {
      const y = 10 + i * LH, q = Math.max(1, Math.round(Math.abs(c.valor) / por)), pos = c.valor >= 0, [f, l] = pos ? ['#5BE37D', '#1F9A47'] : ['#FF6B6B', '#A3141F'];
      const destaque = Math.abs(c.valor) === maior;
      s += `<text class="rot" x="${R - 10}" y="${y + 25}" text-anchor="end" font-size="25" fill="${txt}"${destaque ? '' : ' fill-opacity=".85"'}>${escA(c.texto)}</text>`;
      for (let k = 0; k < q; k++) s += tijoloFrente(pos ? EIXO + 6 + k * TW : EIXO - 6 - (k + 1) * TW, y, TW - 3, TH, f, l);
      const xv = pos ? EIXO + 12 + q * TW : EIXO - 12 - q * TW;
      s += `<text class="valor" x="${xv}" y="${y + 26}" text-anchor="${pos ? 'start' : 'end'}" font-size="27" fill="${txt}">${c.valor > 0 ? '+' : '−'}${escA(fmtA(Math.abs(c.valor)))}</text>`;
    });
    return s + '</svg>';
  }
  // Emissões: colunas de tijolos de CO₂ por potência. colunas: [{ pid, valor }]
  function tijolosCO2(colunas, { unidade = ' Gt', casas = 1, max, tijolos = 8, titulo = 'Emissões de CO₂' } = {}) {
    const topo = max ?? Math.max(1, ...colunas.map(c => c.valor)), n = colunas.length, muitas = n > 8, W = 58, H = 26, GAP = muitas ? 14 : 26;
    const larg = n * W + (n - 1) * GAP + 40, alt = tijolos * H + 112, base = alt - 64;
    let s = `<svg class="grafico co2" viewBox="0 0 ${larg} ${alt}" role="img" aria-label="${escA(titulo + ': ' + colunas.map(c => `${nomeA(c.pid)} ${fmtA(c.valor, casas)}${unidade}`).join('; '))}">`;   // título com CO₂ só no aria-label
    s += `<rect x="4" y="${base}" width="${larg - 8}" height="20" rx="6" fill="#98A6C2" stroke="${TINTA_A}" stroke-width="3"/><rect x="6" y="${base + 1.5}" width="${larg - 12}" height="12" rx="5" fill="#E3E9F4"/>`;
    colunas.forEach((c, i) => {
      const qt = Math.max(c.valor > 0 ? 1 : 0, Math.round(Math.min(c.valor, topo) / topo * tijolos)), x = 20 + i * (W + GAP);
      for (let k = 0; k < qt; k++) s += tijoloFrente(x, base - (k + 1) * H + 1, W, H, '#4A4F5C', '#2B2747', { pinos: k === qt - 1 ? 2 : 0, rotulo: 'CO<tspan dy="3" font-size="72%">2</tspan>' });
      s += `<text class="valor" x="${x + W / 2}" y="${base - qt * H - 14}" text-anchor="middle" font-size="22" fill="${TINTA_A}">${escA(fmtA(c.valor, casas))}</text>`;
      s += formaSVG(c.pid, x + W / 2, base + 10, muitas ? 32 : 22) + (muitas ? '' : `<text class="rot" x="${x + W / 2}" y="${base + 48}" text-anchor="middle" font-size="19" fill="${TINTA_A}">${escA(nomeA(c.pid))}</text>`);
    });
    return s + '</svg>';
  }
  // Matriz energética: fileira de peças (limpa = verde com raio; fóssil = grafite com chaminé)
  function matrizEnergia(limpas, total = 10) {
    const W = 44, G = 8, larg = total * (W + G) - G + 8;
    let s = `<svg class="grafico matriz" viewBox="0 0 ${larg} 70" role="img" aria-label="Matriz energética: ${limpas} de ${total} partes limpas">`;
    for (let i = 0; i < total; i++) {
      const limpa = i < limpas, x = 4 + i * (W + G);
      s += tijoloFrente(x, 20, W, 44, limpa ? '#3CD46A' : '#4A4F5C', limpa ? '#1F9A47' : '#2B2747');
      s += limpa ? `<path d="M${x + 25} 26l-10 15h7l-3 13 11-17h-7l3-11Z" fill="#FFD21F" stroke="${TINTA_A}" stroke-width="2.4" stroke-linejoin="round"/>`
        : `<rect x="${x + 26}" y="6" width="10" height="18" rx="2" fill="#6C6E68" stroke="${TINTA_A}" stroke-width="2.4"/><circle cx="${x + 33}" cy="2" r="4" fill="#8A8F9E" fill-opacity=".8"/>`;
    }
    return s + '</svg>';
  }

  // ---------- Medidores ----------
  // Termômetro deitado de 13 tijolos (0,1 °C cada, de 1,0 a 2,3) com bulbo e bandeirinhas 1,5 (Paris), 2,0 e ✕
  function termometroTijolos(temp, { min = 1.0, max = 2.3, valor = true } = {}) {
    const N = Math.round((max - min) * 10), TW = 30, G = 4, X0 = 70, Y = 50, H = 36, larg = X0 + N * (TW + G) + 18;
    const cor = t => (t <= 1.5 ? '#FFC93C' : t <= 2.0 ? '#FF8A1F' : '#E8322B');
    let s = `<svg class="medidor termometro" viewBox="0 -30 ${larg} 150" role="img" aria-label="Temperatura: ${fmtA(temp, 2)} graus acima da era pré-industrial">`;
    s += `<rect x="${X0 - 12}" y="${Y - 6}" width="${N * (TW + G) + 22}" height="${H + 12}" rx="14" fill="#2E2752" stroke="${TINTA_A}" stroke-width="4"/>`;
    for (let i = 0; i < N; i++) {
      const t = min + (i + 1) * .1, cheio = temp >= t - .049, x = X0 + i * (TW + G);
      s += cheio ? tijoloFrente(x, Y, TW, H, cor(t), mistA(cor(t), TINTA_A, .3)) : `<rect x="${x}" y="${Y}" width="${TW}" height="${H}" rx="6" fill="#4B4475" stroke="${TINTA_A}" stroke-width="2.4"/>`;
    }
    const bulbo = cor(Math.max(temp, min + .1));
    s += `<circle cx="40" cy="${Y + H / 2 + 4}" r="30" fill="${mistA(bulbo, TINTA_A, .3)}" stroke="${TINTA_A}" stroke-width="4.5"/><circle cx="40" cy="${Y + H / 2}" r="28" fill="${bulbo}" stroke="${TINTA_A}" stroke-width="4.5"/><ellipse cx="31" cy="${Y + 8}" rx="9" ry="5" fill="#fff" fill-opacity=".7" transform="rotate(-30 31 ${Y + 8})"/>`;
    const marca = (t, txt, corB, nivel = 0) => { const x = X0 + Math.round((t - min) * 10) * (TW + G) - G / 2, y = 4 - nivel * 30;
      const xis = txt === 'x', w = xis ? 34 : txt.length * 15 + 24;
      return `<path d="M${x} ${Y - 6}V${y + 2}" stroke="${TINTA_A}" stroke-width="3.6" stroke-linecap="round"/><path d="M${x} ${y}h${w}l-7 12 7 12H${x}Z" fill="${corB}" stroke="${TINTA_A}" stroke-width="3" stroke-linejoin="round"/>` +
        (xis ? `<path d="M${x + 8} ${y + 6}l11 12M${x + 19} ${y + 6}l-11 12" stroke="${TINTA_A}" stroke-width="4" stroke-linecap="round"/>` : `<text x="${x + 9}" y="${y + 21}" font-size="21" fill="${TINTA_A}" class="marca-txt">${txt}</text>`); };
    s += marca(1.5, '1,5', '#FFF9EC') + marca(2.0, '2,0', '#FFE3D0') + marca(2.2, 'x', '#FF6B6B', 1);
    if (valor) s += `<text x="${X0 - 4}" y="${Y + H + 40}" font-size="24" fill="${TINTA_A}">${escA(fmtA(temp, 2))} °C</text>`;
    return s + '</svg>';
  }
  // Relógio do Juízo Final: arco de 270° com só os últimos 5 minutos; meia-noite no alto. segundos: 0–300
  function relogioJuizo(segundos, { grande = false } = {}) {
    const s0 = Math.max(0, Math.min(300, segundos)), ang = sec => 360 - sec / 300 * 270;   // graus a partir do alto, horário
    const p = (a, r) => [n1A(100 + Math.sin(a * Math.PI / 180) * r), n1A(100 - Math.cos(a * Math.PI / 180) * r)];
    const arco = (a1, a2, r) => { const [x1, y1] = p(a1, r), [x2, y2] = p(a2, r); return `M${x1} ${y1}A${r} ${r} 0 ${a2 - a1 > 180 ? 1 : 0} 1 ${x2} ${y2}`; };
    let s = `<svg class="medidor relogio${grande ? ' grande' : ''}" viewBox="0 ${grande ? -36 : 0} 200 ${grande ? 246 : 210}" role="img" aria-label="Relógio do Juízo Final: ${Math.round(s0)} segundos para a meia-noite">`;
    s += `<circle cx="100" cy="106" r="92" fill="#B3AA98" stroke="${TINTA_A}" stroke-width="8"/><circle cx="100" cy="100" r="92" fill="#FFF9EC" stroke="${TINTA_A}" stroke-width="8"/>`;
    s += `<path d="${arco(90, 360, 70)}" fill="none" stroke="#E3E9F4" stroke-width="22"/>`;
    s += `<path d="${arco(ang(60), ang(15), 70)}" fill="none" stroke="#FF5A1F" stroke-width="22"/><path d="${arco(ang(15), 360, 70)}" fill="none" stroke="#D7263D" stroke-width="22"/>`;
    for (let k = 0; k <= 10; k++) { const a = ang(k * 30), [x1, y1] = p(a, 56), [x2, y2] = p(a, 84); s += `<path d="M${x1} ${y1}L${x2} ${y2}" stroke="${TINTA_A}" stroke-width="${k % 2 ? 4 : 7}" stroke-linecap="round"/>`; }
    s += `<path d="M30 52a84 84 0 0 1 60 -38" fill="none" stroke="#fff" stroke-width="7" stroke-linecap="round" stroke-opacity=".8"/>`;
    if (grande) {
      for (let m = 1; m <= 5; m++) { const [x, y] = p(ang(m * 60), 40); s += `<text x="${x}" y="${n1A(y + 6)}" text-anchor="middle" font-size="17" fill="${TINTA_A}">${m}</text>`; }
      s += `<path d="M58 -30h84a8 8 0 0 1 8 8v16a8 8 0 0 1-8 8h-34l-8 9-8-9H58a8 8 0 0 1-8-8v-16a8 8 0 0 1 8-8Z" fill="#FFD21F" stroke="${TINTA_A}" stroke-width="4.5" stroke-linejoin="round"/>` +
        `<text x="100" y="-8" text-anchor="middle" font-size="16" fill="${TINTA_A}" style="font-family:'Titan One',sans-serif">MEIA-NOITE</text>`;
    }
    const a = ang(s0);
    s += `<g class="ponteiro" style="transform-origin:100px 100px;transform:rotate(${n1A(a)}deg)"><path d="M100 112V30" stroke="${TINTA_A}" stroke-width="11" stroke-linecap="round"/><path d="M100 30l-9 16h18Z" fill="#FFD21F" stroke="${TINTA_A}" stroke-width="4" stroke-linejoin="round"/></g>`;
    s += `<circle cx="100" cy="100" r="12" fill="#FFD21F" stroke="${TINTA_A}" stroke-width="5"/><circle cx="96" cy="96" r="3.5" fill="#fff"/>`;
    return s + '</svg>';
  }
  // Ponteiro semicircular da energia (preço 0–100): zonas menta / ladrilho-2 / pêssego; marcas 35, 50, 70
  function ponteiroEnergia(valor) {
    const v = Math.max(0, Math.min(100, valor)), p = (t, r) => { const a = Math.PI * (1 - t / 100); return [n1A(100 + Math.cos(a) * r), n1A(104 - Math.sin(a) * r)]; };
    const arco = (t1, t2, r) => { const [x1, y1] = p(t1, r), [x2, y2] = p(t2, r); return `M${x1} ${y1}A${r} ${r} 0 0 1 ${x2} ${y2}`; };
    let s = `<svg class="medidor energia" viewBox="0 0 200 124" role="img" aria-label="Preço da energia: ${Math.round(v)} de 100">`;
    s += `<path d="M8 104a92 92 0 0 1 184 0Z" fill="#B3AA98" stroke="${TINTA_A}" stroke-width="7" stroke-linejoin="round" transform="translate(0 6)"/><path d="M8 104a92 92 0 0 1 184 0Z" fill="#FFF9EC" stroke="${TINTA_A}" stroke-width="7" stroke-linejoin="round"/>`;
    s += `<path d="${arco(0, 35, 68)}" fill="none" stroke="#B3EFC6" stroke-width="26"/><path d="${arco(35, 70, 68)}" fill="none" stroke="#F3EAD6" stroke-width="26"/><path d="${arco(70, 100, 68)}" fill="none" stroke="#FFC4AE" stroke-width="26"/>`;
    for (const t of [35, 50, 70]) { const [x1, y1] = p(t, 52), [x2, y2] = p(t, 84); s += `<path d="M${x1} ${y1}L${x2} ${y2}" stroke="${TINTA_A}" stroke-width="4.5" stroke-linecap="round"/>`; }
    const [px, py] = p(v, 74);
    s += `<path d="M100 104L${px} ${py}" stroke="${TINTA_A}" stroke-width="10" stroke-linecap="round"/><circle cx="100" cy="104" r="11" fill="#FFD21F" stroke="${TINTA_A}" stroke-width="5"/>`;
    return s + '</svg>';
  }
  // Anel de progresso da missão secreta: 8 segmentos curvos (cheios amarelos, vazios encaixe)
  function anelProgresso(n, total = 8) {
    const seg = 360 / total, p = (a, r) => [n1A(50 + Math.sin(a * Math.PI / 180) * r), n1A(50 - Math.cos(a * Math.PI / 180) * r)];
    let s = `<svg class="medidor anel" viewBox="0 0 100 100" role="img" aria-label="Missão: ${n} de ${total} passos">`;
    for (let i = 0; i < total; i++) {
      const a1 = i * seg + 2.5, a2 = (i + 1) * seg - 2.5, [x1, y1] = p(a1, 40), [x2, y2] = p(a2, 40), cheio = i < n;
      s += `<path d="M${x1} ${y1}A40 40 0 0 1 ${x2} ${y2}" fill="none" stroke="${TINTA_A}" stroke-width="16" stroke-linecap="round"/><path d="M${x1} ${y1}A40 40 0 0 1 ${x2} ${y2}" fill="none" stroke="${cheio ? '#FFD21F' : '#4B4475'}" stroke-width="9" stroke-linecap="round"/>`;
    }
    return s + `<text x="50" y="58" text-anchor="middle" font-size="24" fill="#fff" stroke="${TINTA_A}" stroke-width="6" paint-order="stroke">${n}/${total}</text></svg>`;
  }
  // Encaixes redondos que recebem pinos coloridos (deslocados, liderança continental). lista: pids ou cores; total de vagas
  function encaixes(lista, total) {
    const R = 13, P = 34, larg = total * P + 6;
    let s = `<svg class="medidor encaixes" viewBox="0 0 ${larg} 40" role="img" aria-label="${lista.length} de ${total}">`;
    for (let i = 0; i < total; i++) {
      const cx = 3 + P / 2 + i * P, item = lista[i];
      s += `<circle cx="${cx}" cy="20" r="${R + 2}" fill="#2E2752" stroke="${TINTA_A}" stroke-width="3"/><circle cx="${cx}" cy="21" r="${R - 4}" fill="#4B4475"/>`;
      if (item) { const [f, l] = corPeca(item); s += `<circle cx="${cx}" cy="20" r="${R - 1}" fill="${l}" stroke="${TINTA_A}" stroke-width="2.6"/><circle cx="${cx}" cy="17" r="${R - 1}" fill="${f}" stroke="${TINTA_A}" stroke-width="2.6"/><ellipse cx="${cx - 4}" cy="13" rx="4" ry="2.4" fill="#fff" fill-opacity=".85"/>`; }
    }
    return s + '</svg>';
  }
  return { corPeca, tijoloFrente, formaSVG, cabecalhoJornal, seloExtra, tarjaPlantao, vinhetaPlantao, animarVinheta, fita, conquista, tiquete, ponteiroVez, graficoTijolos, graficoLinhas, cascata, tijolosCO2, matrizEnergia, termometroTijolos, relogioJuizo, ponteiroEnergia, anelProgresso, encaixes };
})();
